import{_ as a,J as i,b as r,e as t,a8 as n,f as c,L as l}from"./chunks/framework.BXWQBDlf.js";const h=JSON.parse('{"title":"GR32_LowLevel","description":"","frontmatter":{"layout":"doc","docType":"api","unit":"GR32_LowLevel","entity":"GR32_LowLevel","kind":"Unit","summary":"Provides low-level memory operations, fast mathematical routines, bit manipulations, coordinate wrapping, and optimized rounding operations.","title":"GR32_LowLevel","date":1789506213000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"api/GR32_LowLevel/index.md","filePath":"api/GR32_LowLevel/index.md","lastUpdated":1789506213000,"timestamp":1789506213000,"datetime":"2026-09-15T21:03:33.000Z"}'),d={name:"api/GR32_LowLevel/index.md"};function p(s,e,L,w,v,f){const o=i("ApiMembers");return r(),t("div",null,[e[0]||(e[0]=n('<h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h2><p>The <code>GR32_LowLevel</code> unit contains performance-critical low-level primitives used extensively across Graphics32. It provides optimized memory fills and copies, fast division, fast arithmetic shifts, range clamping and wrapping functions, and accelerated fast-rounding routines (utilizing CPU instruction set extensions such as SSE2 and SSE4.1 where available).</p><p>Key capabilities provided by this unit include:</p><ul><li><strong>Optimized Memory Operations</strong>: 32-bit and 16-bit array filling and copying routines (<a href="/api/GR32_LowLevel/FillLongword"><code>FillLongword</code></a>, <a href="/api/GR32_LowLevel/FillWord"><code>FillWord</code></a>, <a href="/api/GR32_LowLevel/MoveLongword"><code>MoveLongword</code></a>, <a href="/api/GR32_LowLevel/MoveWord"><code>MoveWord</code></a>).</li><li><strong>Stack Memory Allocation</strong>: Stack-based dynamic memory allocation primitives (<a href="/api/GR32_LowLevel/StackAlloc"><code>StackAlloc</code></a>, <a href="/api/GR32_LowLevel/StackAlloc"><code>StackFree</code></a>).</li><li><strong>Fast Value Manipulation</strong>: Swapping operations (<a href="/api/GR32_LowLevel/Swap"><code>Swap</code></a>, <a href="/api/GR32_LowLevel/Swap"><code>Swap32</code></a>, <a href="/api/GR32_LowLevel/Swap16"><code>Swap16</code></a>, <a href="/api/GR32_LowLevel/Swap16"><code>Swap64</code></a>), conditional swapping (<a href="/api/GR32_LowLevel/TestSwap"><code>TestSwap</code></a>), and range clipping check (<a href="/api/GR32_LowLevel/TestClip"><code>TestClip</code></a>).</li><li><strong>Boundary Clamping, Wrapping &amp; Reflection</strong>: Flexible coordinate mapping functions including <a href="/api/GR32_LowLevel/Clamp"><code>Clamp</code></a>, <a href="/api/GR32_LowLevel/Constrain"><code>Constrain</code></a>, <a href="/api/GR32_LowLevel/SwapConstrain"><code>SwapConstrain</code></a>, <a href="/api/GR32_LowLevel/Wrap"><code>Wrap</code></a>, <a href="/api/GR32_LowLevel/WrapMem"><code>WrapMem</code></a>, <a href="/api/GR32_LowLevel/WrapPow2"><code>WrapPow2</code></a>, <a href="/api/GR32_LowLevel/Mirror"><code>Mirror</code></a>, <a href="/api/GR32_LowLevel/Reflect"><code>Reflect</code></a>, and <a href="/api/GR32_LowLevel/ReflectPow2"><code>ReflectPow2</code></a>.</li><li><strong>Optimal Wrap Function Resolvers</strong>: <a href="/api/GR32_LowLevel/GetOptimalWrap"><code>GetOptimalWrap</code></a>, <a href="/api/GR32_LowLevel/GetOptimalReflect"><code>GetOptimalReflect</code></a>, <a href="/api/GR32_LowLevel/GetWrapProc"><code>GetWrapProc</code></a>, and <a href="/api/GR32_LowLevel/GetWrapProcEx"><code>GetWrapProcEx</code></a> for dynamically selecting optimized wrapping procedure delegates.</li><li><strong>Fast Integer Division</strong>: Accelerated division by 255 and 127 (<a href="/api/GR32_LowLevel/Div255"><code>Div255</code></a>, <a href="/api/GR32_LowLevel/Div255"><code>FastDiv255</code></a>, <a href="/api/GR32_LowLevel/Div255"><code>Div255Round</code></a>, <a href="/api/GR32_LowLevel/Div127"><code>Div127</code></a>).</li><li><strong>Fast Rounding Functions</strong>: High-performance replacement for RTL rounding and truncation routines (<a href="/api/GR32_LowLevel/Fast Rounding Functions"><code>FastFloor, FastCeil, FastTrunc, FastRound</code></a>).</li><li><strong>Arithmetic Right Shifts</strong>: Sign-preserving bitwise right shifts (<a href="/api/GR32_LowLevel/SAR"><code>SAR_3</code></a> through <a href="/api/GR32_LowLevel/SAR"><code>SAR_16</code></a>).</li><li><strong>Color Processing</strong>: Color format conversion between VCL/WinAPI <code>TColor</code> and 32-bit <code>TColor32</code> via <a href="/api/GR32_LowLevel/ColorSwap"><code>ColorSwap</code></a>.</li></ul><hr>',5)),c("p",null,[l(o,{type:"members"})])])}const R=a(d,[["render",p]]);export{h as __pageData,R as default};
